CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=100), avatar_url text NOT NULL DEFAULT '' CHECK(length(avatar_url)<=2048));
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_studio_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),100)); RETURN NEW; END $$;
CREATE TRIGGER studio_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_studio_profile();
CREATE TABLE public.studio_content (kind text NOT NULL CHECK(kind IN ('portfolio','categories','packages','addOns','testimonials','settings')), id text NOT NULL CHECK(length(id)<=100), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kind,id));
GRANT SELECT ON public.studio_content TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.studio_content TO authenticated; GRANT ALL ON public.studio_content TO service_role;
ALTER TABLE public.studio_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_content ON public.studio_content FOR SELECT TO anon,authenticated USING(kind IN ('portfolio','packages','addOns','categories','settings') OR (kind='testimonials' AND data->>'published'='true'));
CREATE POLICY admin_content ON public.studio_content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), data jsonb NOT NULL, status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Contacted','Follow-up','Quotation Sent','Converted','Cancelled')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.contact_submissions TO authenticated; GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_contacts ON public.contact_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.quote_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), data jsonb NOT NULL, estimate integer NOT NULL CHECK(estimate>=0), status text NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Sent','Accepted','Declined')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,DELETE ON public.quote_submissions TO authenticated; GRANT ALL ON public.quote_submissions TO service_role;
ALTER TABLE public.quote_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_quotes ON public.quote_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.inquiry_rate_limits (key text PRIMARY KEY, hits integer NOT NULL DEFAULT 1, window_start timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.inquiry_rate_limits TO service_role;
ALTER TABLE public.inquiry_rate_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.allow_inquiry(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN INSERT INTO public.inquiry_rate_limits(key) VALUES(_key) ON CONFLICT(key) DO UPDATE SET hits=CASE WHEN inquiry_rate_limits.window_start<now()-interval '1 hour' THEN 1 ELSE inquiry_rate_limits.hits+1 END, window_start=CASE WHEN inquiry_rate_limits.window_start<now()-interval '1 hour' THEN now() ELSE inquiry_rate_limits.window_start END RETURNING hits INTO n; RETURN n<=10; END $$;
REVOKE ALL ON FUNCTION public.allow_inquiry(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.allow_inquiry(text) TO service_role;